question.en:
Two requests are handled at the same time. What will be logged?
```js
const { AsyncLocalStorage } = require('node:async_hooks');
const store = new AsyncLocalStorage();
let currentId = null;

async function handle(id) {
  currentId = id;
  await new Promise((resolve) => setTimeout(resolve, id === 'a' ? 30 : 5));
  console.log('module var:', currentId, '| store:', store.getStore());
}

store.run('a', () => handle('a'));
store.run('b', () => handle('b'));
```

